import fs from "node:fs";
import ts from "typescript";
const src = ts.transpileModule(fs.readFileSync("lib/data.ts", "utf8"), {
  compilerOptions: {
    module: ts.ModuleKind.ESNext,
    target: ts.ScriptTarget.ES2020,
  },
}).outputText;
const data = await import(
  "data:text/javascript;base64," + Buffer.from(src).toString("base64")
);
const quote = (s) => "'" + s.replaceAll("'", "''") + "'";
const val = (v) =>
  Array.isArray(v)
    ? `array[${v.map(quote)}]::text[]`
    : typeof v === "string"
      ? quote(v)
      : String(v);
let sql =
  "-- Generated by npm run seed:generate. Never overwrites existing content.\nbegin;\n";
for (const [key, table] of Object.entries({
  DIVISIONS: "business_divisions",
  SERVICES: "services",
  PRODUCTS: "products",
  PROJECTS: "projects",
  INDUSTRIES: "industries",
  PUBLICATIONS: "publications",
  VACANCIES: "careers",
})) {
  for (const [i, row] of data[key].entries()) {
    const obj = { ...row };
    if (key === "SERVICES") {
      obj.division_name = obj.division;
      delete obj.division;
    }
    if (key === "PUBLICATIONS") {
      obj.published_at = obj.date;
      delete obj.date;
    }
    if (key === "DIVISIONS" || key === "INDUSTRIES") obj.sort_order = i + 1;
    sql += `insert into public.${table} (${Object.keys(obj).join(",")}) values (${Object.values(obj).map(val).join(",")}) on conflict(slug) do nothing;\n`;
  }
}
fs.writeFileSync(
  "supabase/seed.sql",
  sql +
    "update public.services s set division_id=d.id from public.business_divisions d where s.division_id is null and s.division_name=d.name;\ncommit;\n",
);
